const Label = styled.div`
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeSm};
  color: ${theme.colors.mainTextMuted};
  text-align: center;
`;

const TimeLabel = styled.div`
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeMd};
  font-weight: 600;
  color: ${theme.colors.mainText};
  text-align: center;
`;

function pad2(n: number): string {
  return n.toString().padStart(2, '0');
}

function hourToText(h: number, m: number, locale: string): string {
  if (locale === 'pt') {
    const hStr = h === 1 ? '1 hora' : `${h} horas`;
    if (m === 0) return hStr;
    if (m === 15) return `${hStr} e um quarto`;
    if (m === 30) return `${hStr} e meia`;
    if (m === 45) return `um quarto para as ${h === 12 ? 1 : h + 1}`;
    return `${hStr} e ${m} minutos`;
  }
  const period = h < 12 ? 'AM' : 'PM';
  const h12 = h % 12 || 12;
  if (m === 0) return `${h12} o'clock ${period}`;
  if (m === 15) return `quarter past ${h12} ${period}`;
  if (m === 30) return `half past ${h12} ${period}`;
  if (m === 45) return `quarter to ${(h12 % 12) + 1} ${period}`;
  return `${h12}:${pad2(m)} ${period}`;
}

function AnalogClock({ hours, minutes, seconds }: { hours: number; minutes: number; seconds: number }) {
  const size = 200;
  const cx = size / 2;
  const cy = size / 2;
  const r = 85;

  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const secondAngle = (seconds / 60) * 360 - 90;
  const minuteAngle = (minutes / 60) * 360 + (seconds / 60) * 6 - 90;
  const hourAngle = ((hours % 12) / 12) * 360 + (minutes / 60) * 30 - 90;

  const secX = cx + (r - 24) * Math.cos(toRad(secondAngle));
  const secY = cy + (r - 24) * Math.sin(toRad(secondAngle));
  const minX = cx + (r - 20) * Math.cos(toRad(minuteAngle));
  const minY = cy + (r - 20) * Math.sin(toRad(minuteAngle));
  const hrX = cx + (r - 40) * Math.cos(toRad(hourAngle));
  const hrY = cy + (r - 40) * Math.sin(toRad(hourAngle));

  return (
    <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size}>
      {/* Clock face */}
      <circle cx={cx} cy={cy} r={r} fill={theme.colors.surface} stroke={theme.colors.border} strokeWidth={2} />

      {/* Hour numbers */}
      {Array.from({ length: 12 }, (_, i) => {
        const n = i + 1;
        const angle = (n / 12) * 360 - 90;
        const nx = cx + (r - 16) * Math.cos(toRad(angle));
        const ny = cy + (r - 16) * Math.sin(toRad(angle));
        return (
          <text key={n} x={nx} y={ny + 4} fill={theme.colors.mainText} fontSize={14} fontWeight={600} textAnchor="middle" fontFamily={theme.typography.fontFamily}>
            {n}
          </text>
        );
      })}

      {/* Minute ticks */}
      {Array.from({ length: 60 }, (_, i) => {
        const angle = (i / 60) * 360 - 90;
        const isHour = i % 5 === 0;
        const outerR = r - 2;
        const innerR = isHour ? r - 10 : r - 6;
        return (
          <line
            key={i}
            x1={cx + innerR * Math.cos(toRad(angle))}
            y1={cy + innerR * Math.sin(toRad(angle))}
            x2={cx + outerR * Math.cos(toRad(angle))}
            y2={cy + outerR * Math.sin(toRad(angle))}
            stroke={isHour ? theme.colors.mainTextMuted : theme.colors.border}
            strokeWidth={isHour ? 2 : 1}
          />
        );
      })}

      {/* Hour hand */}
      <line x1={cx} y1={cy} x2={hrX} y2={hrY} stroke={theme.colors.mainText} strokeWidth={4} strokeLinecap="round" />

      {/* Minute hand */}
      <line x1={cx} y1={cy} x2={minX} y2={minY} stroke={theme.colors.accent} strokeWidth={2.5} strokeLinecap="round" />

      {/* Second hand */}
      <line
        x1={cx - 12 * Math.cos(toRad(secondAngle))}
        y1={cy - 12 * Math.sin(toRad(secondAngle))}
        x2={secX} y2={secY}
        stroke="#f87171" strokeWidth={1.2} strokeLinecap="round"
      />

      {/* Center dot */}
      <circle cx={cx} cy={cy} r={4} fill={theme.colors.accent} />
      <circle cx={cx} cy={cy} r={2} fill="#f87171" />
    </svg>
  );
}

interface ClockConfig {
  locale: string;
}

function parseClockCode(code: string): ClockConfig {
  let locale = 'pt';
  for (const line of code.trim().split('\n')) {
    const [key, ...rest] = line.split(':');
    const val = rest.join(':').trim();
    if (key.trim().toLowerCase() === 'locale') locale = val.toLowerCase();
  }
  return { locale };
}

export function ClockBlock({ code }: { code: string }) {
  const config = parseClockCode(code);
  const [mode, setMode] = useState<'live' | 'manual'>('live');
  const [hours, setHours] = useState(() => new Date().getHours());
  const [minutes, setMinutes] = useState(() => new Date().getMinutes());
  const [seconds, setSeconds] = useState(() => new Date().getSeconds());

  useEffect(() => {
    if (mode !== 'live') return;
    const tick = () => {
      const now = new Date();
      setHours(now.getHours());
      setMinutes(now.getMinutes());
      setSeconds(now.getSeconds());
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [mode]);

  const adjustHours = useCallback((delta: number) => {
    setMode('manual');
    setSeconds(0);
    setHours((h) => ((h + delta) % 24 + 24) % 24);
  }, []);

  const adjustMinutes = useCallback((delta: number) => {
    setMode('manual');
    setSeconds(0);
    setMinutes((m) => ((m + delta) % 60 + 60) % 60);
  }, []);

  const goLive = useCallback(() => setMode('live'), []);

  const presets = [
    { label: '3:00', h: 3, m: 0 },
    { label: '6:30', h: 6, m: 30 },
    { label: '9:15', h: 9, m: 15 },
    { label: '12:00', h: 12, m: 0 },
    { label: '13:45', h: 13, m: 45 },
    { label: '15:30', h: 15, m: 30 },
    { label: '19:00', h: 19, m: 0 },
    { label: '23:15', h: 23, m: 15 },
  ];

  return (
    <Wrapper>
      <ClockRow>
        <AnalogClock hours={hours} minutes={minutes} seconds={seconds} />
        <div>
          <Digital>{pad2(hours)}:{pad2(minutes)}<span style={{ fontSize: '24px', opacity: 0.5 }}>:{pad2(seconds)}</span></Digital>
          <TimeLabel>{hourToText(hours % 12 || 12, minutes, config.locale)}</TimeLabel>
        </div>
      </ClockRow>

      <Controls>
        <Btn onClick={() => adjustHours(-1)}>−1h</Btn>
        <Btn onClick={() => adjustHours(1)}>+1h</Btn>
        <Btn onClick={() => adjustMinutes(-15)}>−15m</Btn>
        <Btn onClick={() => adjustMinutes(15)}>+15m</Btn>
        <Btn onClick={() => adjustMinutes(-5)}>−5m</Btn>
        <Btn onClick={() => adjustMinutes(5)}>+5m</Btn>
        <Btn active={mode === 'live'} onClick={goLive}>
          {config.locale === 'pt' ? 'Agora' : 'Now'}
        </Btn>
      </Controls>

      <Label>
        {config.locale === 'pt'
          ? 'Usa os botões para mudar as horas e os minutos!'
          : 'Use the buttons to change the hours and minutes!'}
      </Label>

      <Controls>
        {presets.map((p) => (
          <Btn
            key={p.label}
            onClick={() => { setMode('manual'); setHours(p.h); setMinutes(p.m); }}
          >
            {p.label}
          </Btn>
        ))}
      </Controls>
    </Wrapper>
  );
}

export default ClockBlock;
