import type { AppProgress, LessonProgress } from './types';

const KEY = 'atlantis-leitor-progress';

const DEFAULT_PROGRESS: AppProgress = {
  totalStars: 0,
  level: 1,
  streak: 0,
  lastPlayedDate: '',
  lessons: {},
  favorites: [],
  badges: [],
};

export function loadProgress(): AppProgress {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return { ...DEFAULT_PROGRESS };
    return { ...DEFAULT_PROGRESS, ...JSON.parse(raw) };
  } catch {
    return { ...DEFAULT_PROGRESS };
  }
}

export function saveProgress(progress: AppProgress): void {
  try {
    localStorage.setItem(KEY, JSON.stringify(progress));
  } catch {
    // ignore quota errors
  }
}

export function updateLessonProgress(
  progress: AppProgress,
  lessonId: string,
  score: number,
  total: number,
): AppProgress {
  const stars = score >= total ? 3 : score >= total - 1 ? 2 : score >= Math.ceil(total / 2) ? 1 : 0;
  const existing = progress.lessons[lessonId];
  const best = Math.max(existing?.bestScore ?? 0, score);
  const bestStars = best >= total ? 3 : best >= total - 1 ? 2 : best >= Math.ceil(total / 2) ? 1 : 0;

  const gained = Math.max(0, bestStars - (existing?.stars ?? 0));

  const today = new Date().toISOString().split('T')[0];
  const wasYesterday = (() => {
    if (!progress.lastPlayedDate) return false;
    const last = new Date(progress.lastPlayedDate);
    const diff = (new Date(today).getTime() - last.getTime()) / 86400000;
    return diff === 1;
  })();

  return {
    ...progress,
    totalStars: progress.totalStars + gained,
    level: Math.floor((progress.totalStars + gained) / 5) + 1,
    streak: progress.lastPlayedDate === today
      ? progress.streak
      : wasYesterday
      ? progress.streak + 1
      : 1,
    lastPlayedDate: today,
    lessons: {
      ...progress.lessons,
      [lessonId]: {
        stars: bestStars,
        bestScore: best,
        completed: bestStars > 0,
      },
    },
  };
}

export function toggleFavorite(progress: AppProgress, cardKey: string): AppProgress {
  const isFav = progress.favorites.includes(cardKey);
  return {
    ...progress,
    favorites: isFav
      ? progress.favorites.filter((f) => f !== cardKey)
      : [...progress.favorites, cardKey],
  };
}

export function addBadge(progress: AppProgress, badge: string): AppProgress {
  if (progress.badges.includes(badge)) return progress;
  return { ...progress, badges: [...progress.badges, badge] };
}

export function checkBadges(progress: AppProgress): AppProgress {
  let p = progress;
  if (p.totalStars >= 1 && !p.badges.includes('primeira-estrela')) p = addBadge(p, 'primeira-estrela');
  const completed = Object.values(p.lessons).filter((l) => l.completed).length;
  if (completed >= 1 && !p.badges.includes('primeira-licao')) p = addBadge(p, 'primeira-licao');
  const hasThreeStars = Object.values(p.lessons).some((l) => l.stars === 3);
  if (hasThreeStars && !p.badges.includes('tres-estrelas')) p = addBadge(p, 'tres-estrelas');
  if (p.favorites.length >= 10 && !p.badges.includes('coleccionador')) p = addBadge(p, 'coleccionador');
  if (p.lessons['vogais']?.stars === 3 && !p.badges.includes('vogais-mestre')) p = addBadge(p, 'vogais-mestre');
  const silabasDone = ['silabas-b','silabas-c','silabas-d','silabas-f','silabas-g','silabas-l','silabas-m','silabas-n','silabas-p','silabas-r','silabas-s','silabas-t','silabas-v'].every(
    (id) => p.lessons[id]?.completed,
  );
  if (silabasDone && !p.badges.includes('leitor')) p = addBadge(p, 'leitor');
  const mundoDone = ['animais', 'cores', 'numeros', 'corpo', 'familia'].every(
    (id) => p.lessons[id]?.completed,
  );
  if (mundoDone && !p.badges.includes('explorador')) p = addBadge(p, 'explorador');
  if (p.lessons['numeros']?.stars === 3 && !p.badges.includes('numeros-mestre')) p = addBadge(p, 'numeros-mestre');
  return p;
}
