export function getLessonById(id: string): Lesson | undefined {
  return LESSONS.find((l) => l.id === id);
}

/** Generate up to 5 quiz questions for a lesson */
export function buildQuiz(lesson: Lesson): QuizQuestion[] {
  const cards = [...lesson.cards].sort(() => Math.random() - 0.5).slice(0, 5);

  const isWordLesson   = lesson.id === 'palavras' || lesson.id === 'frases';
  const isLetterLesson = !isWordLesson;

  return cards.map((card) => {
    const wrongCards = lesson.cards.filter((c) => c.id !== card.id);
    const wrongs = wrongCards.sort(() => Math.random() - 0.5).slice(0, 3);

    if (isWordLesson) {
      const opts = [{ emoji: card.emoji }, ...wrongs.map((w) => ({ emoji: w.emoji }))].sort(() => Math.random() - 0.5);
      return {
        type: 'word-to-emoji' as const,
        cardId: card.id,
        promptWord: card.letter,
        label: 'Qual é a imagem?',
        options: opts,
        correctIndex: opts.findIndex((o) => o.emoji === card.emoji),
      };
    }

    if (Math.random() > 0.5) {
      const opts = [{ letter: card.letter }, ...wrongs.map((w) => ({ letter: w.letter }))].sort(() => Math.random() - 0.5);
      return {
        type: 'emoji-to-letter' as const,
        cardId: card.id,
        promptEmoji: card.emoji,
        promptWord: card.word,
        label: lesson.id === 'vogais' ? 'Começa com que letra?' : 'Começa com que sílaba?',
        options: opts,
        correctIndex: opts.findIndex((o) => o.letter === card.letter),
      };
    }

    const opts = [{ emoji: card.emoji }, ...wrongs.map((w) => ({ emoji: w.emoji }))].sort(() => Math.random() - 0.5);
    return {
      type: 'letter-to-emoji' as const,
      cardId: card.id,
      promptLetter: card.letter,
      label: 'Qual é a imagem?',
      options: opts,
      correctIndex: opts.findIndex((o) => o.emoji === card.emoji),
    };
  });
}

